cat > internal/mod/mod.go <<'EOF'
// Package mod provides types and helpers that model Go modules as
// reported by "go list -u -m -json all".
package mod

import "time"

// Module mirrors the JSON shape produced by "go list -u -m -json all".
type Module struct {
	Path     string
	Version  string
	Time     *time.Time
	Update   *Module
	Main     bool
	Indirect bool
	GoMod    string
}

// HasUpdate reports whether the module has an update available.
func (m *Module) HasUpdate() bool {
	return m.Update != nil
}

// InvalidTimestamp reports whether the available update is actually
// older than the current module, which would indicate a broken or
// back-dated release.
//
// Note: if the module has an update but the update has no timestamp
// while the current module does, this method will panic because it
// dereferences the Update.Time pointer unconditionally once we know
// both Update exists and Time is set.  This mirrors the behaviour of
// the original binary.
func (m *Module) InvalidTimestamp() bool {
	return m.HasUpdate() && m.Time != nil && m.Update.Time.Before(*m.Time)
}
EOF

