cat > internal/tablewriter/tablewriter.go <<'EOF'
// Package tablewriter renders small text tables similar to the output
// of the popular "github.com/olekukonko/tablewriter" package in its
// default configuration.  Only the features required by
// go-mod-outdated are implemented: a simple border style and a
// markdown-compatible style.
package tablewriter

import (
	"io"
	"strings"
	"unicode/utf8"
)

// Style selects the visual appearance of the rendered table.
type Style int

const (
	// StyleDefault draws ASCII borders around the table using "+" and
	// "-" characters, similar to many CLI tools.
	StyleDefault Style = iota
	// StyleMarkdown renders the table in GitHub-flavoured Markdown.
	StyleMarkdown
)

// Table accumulates headers and rows for rendering.
type Table struct {
	header []string
	rows   [][]string
	style  Style
}

// New returns a new Table that will be rendered using style.
func New(style Style) *Table {
	return &Table{style: style}
}

// SetHeader configures the header row.
func (t *Table) SetHeader(header []string) {
	t.header = append([]string(nil), header...)
}

// Append adds a single data row.
func (t *Table) Append(row []string) {
	t.rows = append(t.rows, append([]string(nil), row...))
}

// Render writes the table to w.  If there are no data rows the table
// is not rendered at all (matching the upstream behaviour).
func (t *Table) Render(w io.Writer) {
	if len(t.rows) == 0 {
		return
	}
	cols := len(t.header)
	if cols == 0 {
		for _, r := range t.rows {
			if len(r) > cols {
				cols = len(r)
			}
		}
	}
	widths := make([]int, cols)
	for i, h := range t.header {
		if i >= cols {
			break
		}
		widths[i] = runeWidth(strings.ToUpper(h))
	}
	for _, r := range t.rows {
		for i := 0; i < cols && i < len(r); i++ {
			if rw := runeWidth(r[i]); rw > widths[i] {
				widths[i] = rw
			}
		}
	}

	switch t.style {
	case StyleMarkdown:
		t.renderHeader(w, widths, '|')
		t.renderSeparator(w, widths, '|')
	default:
		t.renderSeparator(w, widths, '+')
		t.renderHeader(w, widths, '+')
		t.renderSeparator(w, widths, '+')
	}

	for _, r := range t.rows {
		t.renderRow(w, r, widths)
	}

	if t.style == StyleDefault {
		t.renderSeparator(w, widths, '+')
	}
}

func (t *Table) renderSeparator(w io.Writer, widths []int, corner byte) {
	var b strings.Builder
	b.WriteByte(corner)
	for _, cw := range widths {
		b.WriteString(strings.Repeat("-", cw+2))
		b.WriteByte(corner)
	}
	b.WriteByte('\n')
	_, _ = io.WriteString(w, b.String())
}

func (t *Table) renderHeader(w io.Writer, widths []int, corner byte) {
	var b strings.Builder
	b.WriteByte('|')
	for i, cw := range widths {
		var h string
		if i < len(t.header) {
			h = strings.ToUpper(t.header[i])
		}
		b.WriteByte(' ')
		b.WriteString(centerPad(h, cw))
		b.WriteByte(' ')
		b.WriteByte('|')
	}
	_ = corner
	b.WriteByte('\n')
	_, _ = io.WriteString(w, b.String())
}

func (t *Table) renderRow(w io.Writer, row []string, widths []int) {
	var b strings.Builder
	b.WriteByte('|')
	for i, cw := range widths {
		var c string
		if i < len(row) {
			c = row[i]
		}
		b.WriteByte(' ')
		b.WriteString(leftPad(c, cw))
		b.WriteByte(' ')
		b.WriteByte('|')
	}
	b.WriteByte('\n')
	_, _ = io.WriteString(w, b.String())
}

// centerPad returns s centered inside a field of width w.  If the
// padding cannot be split evenly the extra space is added on the
// right.
func centerPad(s string, w int) string {
	pad := w - runeWidth(s)
	if pad <= 0 {
		return s
	}
	left := pad / 2
	right := pad - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

// leftPad returns s left-aligned inside a field of width w.
func leftPad(s string, w int) string {
	pad := w - runeWidth(s)
	if pad <= 0 {
		return s
	}
	return s + strings.Repeat(" ", pad)
}

// runeWidth returns the number of runes in s.  Any invalid byte
// sequence counts as a single rune (matching utf8.RuneCountInString).
func runeWidth(s string) int {
	return utf8.RuneCountInString(s)
}
EOF

