cat > internal/runner/runner.go <<'EOF'
// Package runner contains the orchestration logic for go-mod-outdated.
// It is responsible for reading the JSON produced by "go list -u -m
// -json all" from stdin, applying the user selected filters, rendering
// the result as a table and computing the process exit code.
package runner

import (
	"encoding/json"
	"fmt"
	"io"
	"strconv"

	"github.com/psampaz/go-mod-outdated/internal/mod"
	"github.com/psampaz/go-mod-outdated/internal/tablewriter"
)

// Run is the main entrypoint.  It decodes the stream of modules from
// in, filters it according to onlyUpdate, onlyDirect and failOnUpdate,
// and writes the resulting table to out.  It returns the desired
// process exit code.
func Run(in io.Reader, out io.Writer, onlyUpdate, onlyDirect, failOnUpdate bool, style string) (int, error) {
	modules, err := decodeModules(in)
	if err != nil {
		return 0, err
	}

	filtered := make([]mod.Module, 0, len(modules))
	for _, m := range modules {
		if m.Main {
			continue
		}
		if onlyDirect && m.Indirect {
			continue
		}
		if onlyUpdate && !m.HasUpdate() {
			continue
		}
		filtered = append(filtered, m)
	}

	renderTable(out, filtered, style)

	if failOnUpdate {
		for i := range filtered {
			if filtered[i].HasUpdate() {
				return 1, nil
			}
		}
	}
	return 0, nil
}

// decodeModules decodes a stream of whitespace-separated JSON module
// objects from r.
func decodeModules(r io.Reader) ([]mod.Module, error) {
	var modules []mod.Module
	dec := json.NewDecoder(r)
	for {
		var m mod.Module
		if err := dec.Decode(&m); err != nil {
			if err == io.EOF {
				break
			}
			return nil, err
		}
		modules = append(modules, m)
	}
	return modules, nil
}

// renderTable writes the table representation of the provided modules
// to out using the given style.
func renderTable(out io.Writer, modules []mod.Module, style string) {
	var s tablewriter.Style
	switch style {
	case "markdown":
		s = tablewriter.StyleMarkdown
	default:
		s = tablewriter.StyleDefault
	}

	t := tablewriter.New(s)
	t.SetHeader([]string{"Module", "Version", "New Version", "Direct", "Valid Timestamps"})

	for i := range modules {
		m := &modules[i]
		newVersion := ""
		if m.HasUpdate() {
			newVersion = m.Update.Version
		}
		t.Append([]string{
			m.Path,
			m.Version,
			newVersion,
			strconv.FormatBool(!m.Indirect),
			strconv.FormatBool(!m.InvalidTimestamp()),
		})
	}

	t.Render(out)
	_ = fmt.Sprintf
}
EOF

